import pandas as pd

df = pd.read_csv("Neuropathic_pairwise_13.csv")

# Calculate the number of times A (L fainting) appears before B (R L5 radiculopathy)
count_a_before_b = 0
for index, row in df.iterrows():
    if row['L fainting'] == 1 and row['R L5 radiculopathy'] == 0:
        count_a_before_b += 1

# Calculate the number of times B (R L5 radiculopathy) appears before A (L fainting)
count_b_before_a = 0
for index, row in df.iterrows():
    if row['R L5 radiculopathy'] == 1 and row['L fainting'] == 0:
        count_b_before_a += 1

# Determine which relationship is more likely based on the counts
if count_a_before_b > count_b_before_a:
    answer = "A"
else:
    answer = "B"

print(answer)

